    'iconClose.width|appearance|status=danger, type=icon-only, invert=true|default':
        't:icon.sm',
    'iconClose.height|appearance|status=danger, type=icon-only, invert=true|default':
        't:icon.sm',
    'iconClose.width|appearance|status=danger, type=icon+text, invert=true|default':
        't:icon.sm',
    'iconClose.height|appearance|status=danger, type=icon+text, invert=true|default':
        't:icon.sm',
    'iconClose.width|appearance|status=danger, type=text-only, invert=true|default':
        't:icon.sm',
    'iconClose.height|appearance|status=danger, type=text-only, invert=true|default':
        't:icon.sm',
    'iconClose.width|appearance|status=info, type=status, invert=true|default':
        't:icon.sm',
    'iconClose.height|appearance|status=info, type=status, invert=true|default':
        't:icon.sm',
    'iconClose.width|appearance|status=info, type=icon-only, invert=true|default':
        't:icon.sm',
    'iconClose.height|appearance|status=info, type=icon-only, invert=true|default':
        't:icon.sm',
    'iconClose.width|appearance|status=info, type=icon+text, invert=true|default':
        't:icon.sm',
    'iconClose.height|appearance|status=info, type=icon+text, invert=true|default':
        't:icon.sm',
    'iconClose.width|appearance|status=info, type=text-only, invert=true|default':
        't:icon.sm',
    'iconClose.height|appearance|status=info, type=text-only, invert=true|default':
        't:icon.sm',
  };

  /// Which state wins when several hold, highest first: the MUI recipe's cascade, read backwards.
  static const List<String> statePrecedence = <String>[];

  static bool _holds(String state, SolarTagProps p, Set<WidgetState> s) =>
      switch (state) {
        _ => false,
      };

  /// The entry for one cell under these props and states, by the IR's precedence: a state that
  /// holds beats the resting value, the per-size-and-appearance entry beats the per-appearance
  /// one, and the resting value falls back through appearance, size and base.
  static String? lookup(String cell, SolarTagProps p, Set<WidgetState> s) {
    final combo =
        'status=${p.status.name}, type=${p.type.figma}, invert=${p.invert}';
    const size = '';
    for (final state in statePrecedence) {
      if (!_holds(state, p, s)) continue;
      final hit =
          cells['$cell|combined|$size|$combo|$state'] ??
          cells['$cell|appearance|$combo|$state'];
      if (hit != null) return hit;
    }
    return cells['$cell|combined|$size|$combo|default'] ??
        cells['$cell|appearance|$combo|default'] ??
        cells['$cell|size|$size'] ??
        cells['$cell|base'];
  }

  static Color color(
    SolarTheme t,
    String cell,
    SolarTagProps p,
    Set<WidgetState> s,
  ) {
    final c = t.colors;
    return switch (lookup(cell, p, s)) {
      'none' => Colors.transparent,
      't:color.border.feedback.danger.subtle' => c.borderFeedbackDangerSubtle,
      't:color.border.feedback.info.subtle' => c.borderFeedbackInfoSubtle,
      't:color.border.feedback.success.subtle' => c.borderFeedbackSuccessSubtle,
      't:color.border.feedback.warning.subtle' => c.borderFeedbackWarningSubtle,
      't:color.border.medium' => c.borderMedium,
      't:color.icon.feedback.danger' => c.iconFeedbackDanger,
      't:color.icon.feedback.info' => c.iconFeedbackInfo,
      't:color.icon.feedback.neutral' => c.iconFeedbackNeutral,
      't:color.icon.feedback.success' => c.iconFeedbackSuccess,
      't:color.icon.feedback.warning' => c.iconFeedbackWarning,
      't:color.icon.inverse' => c.iconInverse,
      't:color.surface.feedback.danger.strong' => c.surfaceFeedbackDangerStrong,
      't:color.surface.feedback.danger.subtle' => c.surfaceFeedbackDangerSubtle,
      't:color.surface.feedback.info.strong' => c.surfaceFeedbackInfoStrong,
      't:color.surface.feedback.info.subtle' => c.surfaceFeedbackInfoSubtle,
      't:color.surface.feedback.neutral.strong' =>
        c.surfaceFeedbackNeutralStrong,
      't:color.surface.feedback.neutral.subtle' =>
        c.surfaceFeedbackNeutralSubtle,
      't:color.surface.feedback.success.strong' =>
        c.surfaceFeedbackSuccessStrong,
      't:color.surface.feedback.success.subtle' =>
        c.surfaceFeedbackSuccessSubtle,
      't:color.surface.feedback.warning.strong' =>
        c.surfaceFeedbackWarningStrong,
      't:color.surface.feedback.warning.subtle' =>
        c.surfaceFeedbackWarningSubtle,
      't:color.text.feedback.danger' => c.textFeedbackDanger,
      't:color.text.feedback.info' => c.textFeedbackInfo,
      't:color.text.feedback.neutral' => c.textFeedbackNeutral,
      't:color.text.feedback.success' => c.textFeedbackSuccess,
      't:color.text.feedback.warning' => c.textFeedbackWarning,
      't:color.text.inverse' => c.textInverse,
      final v => throw StateError('$cell: no colour for $v'),
    };
  }

  static List<BoxShadow> shadow(
    SolarTheme t,
    String cell,
    SolarTagProps p,
    Set<WidgetState> s,
  ) => switch (lookup(cell, p, s)) {
    'none' || null => const <BoxShadow>[],

    final v => throw StateError('$cell: no shadow for $v'),
  };

  /// A length in logical pixels, or null where the IR says the layer hugs its content.
  static double? dimension(String cell, SolarTagProps p, Set<WidgetState> s) {
    final v = lookup(cell, p, s);
    if (v == null || v == 'k:HUG') return null;
    if (v == 'k:FILL') return double.infinity;
    if (v.startsWith('px:')) return double.parse(v.substring(3));
    return switch (v) {
      't:border.default' => SolarBorder.$default,
      't:icon.sm' => SolarIconSize.sm,
      't:icon.xs' => SolarIconSize.xs,
      't:inset.2xs' => SolarInset.$2xs,
      't:inset.none' => SolarInset.none,
      't:inset.sm' => SolarInset.sm,
      't:inset.xs' => SolarInset.xs,
      't:radius.pill' => SolarRadius.pill,
      _ => throw StateError('$cell: no length for $v'),
    };
  }

  static TextStyle? textStyle(
    SolarTheme t,
    String cell,
    SolarTagProps p,
    Set<WidgetState> s,
  ) => switch (lookup(cell, p, s)) {
    'none' || null => null,
    't:typography.label.sm' => t.typography.labelSm,
    final v => throw StateError('$cell: no text style for $v'),
  };

  /// Whether a layer is drawn: the shell reads this, the style does not.
  static bool present(String layer, SolarTagProps p, Set<WidgetState> s) =>
      lookup('$layer.present', p, s) != 'b:false';
}
